package build

import (
	"bytes"
	"os"
	"testing"
)

// Generated by executing serviceContent from c885c6963e0bbebd2e852920e064a8ad7017ab0e,
// not by deleting the marker from the new renderer. The legacy darwin branch
// was extracted unchanged into a standalone Go program with proxyRuntime fields
// below and binary /opt/homebrew/bin/xray; stdout is the checked-in fixture.
// SHA256: a8f61c2a1ecb54d51296b2eddc23656277826a199f0384aec0c1d7357ecab17d.
// This proves that source format only; it does not assert a released artifact.
func TestXrayLegacyPlistUpgradeAndOwnership(t *testing.T) {
	legacy, err := os.ReadFile("testdata/xray-legacy-c885c696.plist")
	if err != nil {
		t.Fatal(err)
	}
	r := proxyRuntime{os: "darwin", label: "com.pigsty.xray-proxy", config: "/Users/fixture/.config/xray/pig-proxy.json"}
	desired, err := r.serviceContent(DefaultProxyListen, "/opt/homebrew/bin/xray")
	if err != nil {
		t.Fatal(err)
	}
	for _, data := range [][]byte{legacy, desired} {
		if !r.serviceFileReplaceable(data, desired) {
			t.Error("same configuration requires replacement confirmation")
		}
	}
	for name, data := range map[string][]byte{
		"changed-legacy":  bytes.ReplaceAll(legacy, []byte("/dev/null"), []byte("/tmp/custom.log")),
		"changed-marked":  bytes.ReplaceAll(desired, []byte("KeepAlive"), []byte("Disabled")),
		"embedded-marker": append([]byte("foreign content\n"), desired...),
		"foreign":         []byte("foreign plist\n"),
	} {
		if r.serviceFileReplaceable(data, desired) {
			t.Errorf("foreign or modified file accepted: %s", name)
		}
	}
}

func TestXraySystemdOwnershipIsExact(t *testing.T) {
	r := proxyRuntime{os: "linux", asset: "/usr/share/xray"}
	low, _ := r.serviceContent("0.0.0.0:443", "/usr/bin/xray")
	high, _ := r.serviceContent("127.0.0.1:9443", "/usr/bin/xray")
	if !r.serviceFileReplaceable(low, high) || !r.serviceFileReplaceable(high, low) {
		t.Fatal("recognized capability change needs replacement")
	}
	if r.serviceFileReplaceable(append(low, []byte("ExecStart=/foreign\n")...), high) {
		t.Fatal("header alone granted ownership of modified systemd file")
	}
}
